    cells = {(r, c) for r in range(h) for c in range(w) if g[r][c] != bg}
    comps = []
    while cells:
        start = cells.pop()
        comp = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in cells:
                    cells.remove(p); comp.add(p); q.append(p)
        comps.append(comp)
    motif = max(comps, key=len)
    r0, r1 = min(r for r,c in motif), max(r for r,c in motif)
    c0, c1 = min(c for r,c in motif), max(c for r,c in motif)
    mh, mw = r1-r0+1, c1-c0+1
    pattern = {(r-r0,c-c0):g[r][c] for r,c in motif}
    markers = [p for comp in comps if comp != motif for p in comp]
    ar, ac = mh//2, mw//2
